import{_ as T,l as o,o as t,c as l,v as e,p as i,x as r,d as n,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"TLS 1.3 与 0-RTT","description":"","frontmatter":{"title":"TLS 1.3 与 0-RTT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tls13-0rtt.md","filePath":"cs/tls13-0rtt.md","lastUpdated":1789023840000}'),h={name:"cs/tls13-0rtt.md"};function A(c,a,p,_,R,m){const s=o("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="tls-1-3-与-0-rtt" tabindex="-1">TLS 1.3 与 0-RTT <a class="header-anchor" href="#tls-1-3-与-0-rtt" aria-label="Permalink to &quot;TLS 1.3 与 0-RTT&quot;">​</a></h1><div class="epigraph"><p>1.3 只保留 AEAD、强制（EC）DHE、压缩握手；0-RTT 用上次票提前发应用数据，换来重放窗口。</p><footer>—— RFC 8446, TLS 1.3</footer></div><p><a href="/cs/tls-handshake">上一课</a>给出握手：证书、派生、记录层 AEAD。本课不重画完整证书链。缺口是 RFC 8446 相对旧版的收缩，以及 <strong>0-RTT</strong>：用预共享的恢复密钥在第一个往返之前发送数据。防火墙下一课是边界上的流状态，不是握手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>握手课用 1.3 当默认叙事。需要钉差：去掉 RSA 密钥传输与非 AEAD 套件（<a href="/cs/dh-vs-rsa">DH 与 RSA 分工</a> 已铺垫），Hello 里带密钥份额，通常 1-RTT 完成。0-RTT：客户端用上次 NewSessionTicket 派生的密钥直接带应用数据。DY 敌手可以<strong>重放</strong>那一段早数据——规格允许，应用必须幂等或拒绝。缺口是<strong>延迟与重放的取舍</strong>。</p><p><span class="marginnote">0-RTT 数据没有前向保密相对于那张票的泄露窗口。服务器可关 0-RTT。HTTP GET 缓存友好请求相对更适合，仍要应用自己判断。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>完整握手：共享秘密进 HKDF，导出流量密钥。恢复：PSK 或票加新鲜 DH（1.3 推荐组合）。0-RTT 密钥从 PSK 导出，服务器在确认后才升级到正式流量密钥。本课不把中间盒对 1.3 可见性的政策写成标准。</p>',8)),(t(),i(E,null,{default:r(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20H13%5B%22TLS%201.3%201-RTT%22%5D%20--%3E%20AEAD%5B%22%E4%BB%85%20AEAD%20%E5%A5%97%E4%BB%B6%22%5D%0A%20%20TICKET%5B%22%E4%BC%9A%E8%AF%9D%E7%A5%A8%22%5D%20--%3E%20ZRTT%5B%220-RTT%20%E6%97%A9%E6%95%B0%E6%8D%AE%22%5D%0A%20%20ZRTT%20--%3E%20REPLAY%5B%22%E5%BA%94%E7%94%A8%E9%A1%BB%E5%81%87%E8%AE%BE%E5%8F%AF%E9%87%8D%E6%94%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>1.3 把模式课与公钥课收成不可再选弱组合。0-RTT 把<a href="/cs/http-semantics">HTTP 幂等</a> 变成安全合同：非幂等请求不应放进早数据。记录层仍服务链路 CIA 的 C/I；端点与 0-RTT 重放是另一轴。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 GREASE 等兼容技巧当必懂。边界网关上谁被放行，下一课防火墙与状态。</p><p>后课默认：1.3 默认 1-RTT；0-RTT 带重放假设。分组过滤是另一层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RFC 8446：AEAD、DHE、更短握手。</li><li>0-RTT 用票换延迟，应用必须当重放。</li><li>防火墙下一课。</li><li>出处：RFC 8446。</li></ul>',7))])}const u=T(h,[["render",A]]);export{f as __pageData,u as default};
